import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')
API_SECRET = os.environ.get('API_SECRET', 'changeme')

def get_db():
    return psycopg2.connect(
        host=DB_HOST, database=DB_NAME,
        user=DB_USER, password=DB_PASS
    )

def verify_hmac(payload, signature):
    """Verify request signature for webhook endpoints"""
    expected = hmac.new(API_SECRET.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports filtering by department."""
    department = request.args.get('department', '')
    status = request.args.get('status', 'active')
    page = request.args.get('page', '1')

    # Input length validation
    if len(department) > 100 or len(status) > 20:
        return jsonify({'error': 'Input too long'}), 400

    # Basic character filter - block obvious attacks
    blocked_chars = [';', '--', '/*', '*/', 'xp_', 'exec', 'execute']
    for bc in blocked_chars:
        if bc.lower() in department.lower():
            return jsonify({'error': 'Invalid characters'}), 400

    try:
        page_num = int(page)
        offset = (page_num - 1) * 25
    except ValueError:
        offset = 0

    conn = get_db()
    cur = conn.cursor()

    # Build query with department filter
    query = f"SELECT id, username, email, department FROM users WHERE status = '{status}' AND department LIKE '%{department}%' ORDER BY username LIMIT 25 OFFSET {offset}"

    try:
        cur.execute(query)
        rows = cur.fetchall()
        users = [{'id': r[0], 'username': r[1], 'email': r[2], 'department': r[3]} for r in rows]
        return jsonify({'users': users, 'page': page_num})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Database error'}), 500
    finally:
        cur.close()
        conn.close()

@app.route('/api/v1/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - parameterized query"""
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT id, username, email, department FROM users WHERE id = %s", (user_id,))
    row = cur.fetchone()
    cur.close()
    conn.close()
    if row:
        return jsonify({'id': row[0], 'username': row[1], 'email': row[2], 'department': row[3]})
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
